Scheme kc__2 := Elimination for OSSVerify.Proofs.boost_beast.http_request.lib.As.X8_pst.pst Sort Prop.
Scheme kc__3 := Elimination for Corelib.Init.Logic.or Sort Prop.
Scheme kc__4 := Elimination for Corelib.Init.Logic.ex Sort Prop.
Scheme kc__5 := Elimination for Corelib.Init.Logic.False Sort Prop.
Scheme kc__6 := Elimination for Corelib.Init.Datatypes.prod Sort Prop.

(* [comment removed for export] *)
(* [comment removed for export] *)
Lemma isl_facts : forall (d : pst) (SP : Z) (mh m' : mem) (s s' : as_St H) (p : Z) (bsw : list byte)
    (c' : pcore) (in' u' : Z) (E' : ecv) (h' : hdrv) (LB' : list block) (g' : bool),
  let LB := ps_LBn d ++ LB0 in let A' := ps_A d + (in' - p) in
  PutL H sp P E p0 bs LB0 (ps_L d0) (ps_es d0) (ps_h d0) d ->
  aceil <= SP -> SP <= bv_unsigned sp -> pc_state (ps_c d) = 1 ->
  as_RHEAP H s LB mh -> AFieldsC mh (P + 80) (ps_S d) (ps_L d) (ps_ns d) (ps_ls d) (ps_em d) -> AMBuf mh (P + 168) (ps_es d) (ps_insz d) ->
  as_RHEAP H s' LB' m' ->
  isl_outcome (ps_c d) p bsw (ps_h d) LB (ps_g d) m' c' in' E' u' h' LB' g' ->
  p0 <= p ->
  exists NEW, LB' = NEW ++ LB
    /\ PutL H sp P E p0 bs LB0 (ps_L d0) (ps_es d0) (ps_h d0)
         (mkPST c' (ps_S d) (ps_L d) (ps_ns d) (ps_ls d) (ps_em d) h' u' (ps_es d) (ps_insz d) g' (ps_rdi d) (NEW ++ ps_LBn d) A')
    /\ lb_bytes NEW <= in' - p /\ Z.of_nat (length NEW) <= 2
    /\ pc_hlim c' = pc_hlim (ps_c d) /\ (pc_state c' = 1 \/ pc_state c' = 2) /\ (pc_state c' = 1 -> in' = p /\ NEW = [])
    /\ HdrOwnA LB' m' h'
    /\ ec_ok E' /\ (E' = EC_clear \/ http_fail E') /\ (E' = EC_clear -> p < in') /\ ec_hc E'
